/**
 * Generates src/environments/environment.generated.ts from ACME_API_BASE_URL, for the
 * production build to use in place of environment.ts (see angular.json).
 *
 * The production API lives on another origin than the static site, and that origin is
 * only known once the backend is deployed. Baking it in at build time keeps it out of
 * the repository without shipping any runtime configuration machinery.
 *
 * The generated file is git-ignored on purpose: a deployment URL must never end up in a
 * tracked source file, not even temporarily after a local build.
 *
 * Run automatically by `npm run build`. With no ACME_API_BASE_URL set, the generated file
 * keeps the same-origin default (`/api`), so the build behaves exactly as it does locally.
 */
import { mkdirSync, writeFileSync } from 'node:fs';
import { dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const TARGET = fileURLToPath(new URL('../src/environments/environment.generated.ts', import.meta.url));
const DEFAULT_BASE_URL = '/api';

// No trailing slash: the services and the auth interceptor append `/...` themselves.
const configured = (process.env.ACME_API_BASE_URL ?? '').trim().replace(/\/+$/, '');

// https anywhere, plain http only against a local backend, or an origin-relative path.
const ALLOWED = /^(https:\/\/[^\s'"]+|http:\/\/(localhost|127\.0\.0\.1)(:\d+)?(\/[^\s'"]*)?|\/[^\s'"]*)$/;

if (configured && !ALLOWED.test(configured)) {
  console.error(
    `set-api-base-url: ACME_API_BASE_URL must be an https:// URL, a http://localhost URL or an origin-relative path, got "${configured}".`,
  );
  process.exit(1);
}

const apiBaseUrl = configured || DEFAULT_BASE_URL;

mkdirSync(dirname(TARGET), { recursive: true });
writeFileSync(
  TARGET,
  `// Generated by scripts/set-api-base-url.mjs. Not tracked in Git; do not edit.
export const environment = {
  apiBaseUrl: '${apiBaseUrl}',
};
`,
);

console.log(`set-api-base-url: apiBaseUrl = ${apiBaseUrl}`);
